<?php namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller; use App\Models\Product; use Illuminate\Http\Request; class WishlistController extends Controller { public function index(Request $r){return $r->user()->wishlist()->with('vendor','images','inventory')->paginate();} public function store(Request $r){$d=$r->validate(['product_id'=>'required|exists:products,id']);$r->user()->wishlist()->syncWithoutDetaching([$d['product_id']]);return response()->noContent(201);} public function destroy(Request $r,Product $product){$r->user()->wishlist()->detach($product);return response()->noContent();} }
